    m = re.search(r'<script[^>]*id="__NUXT_DATA__"[^>]*>(.*?)</script>', html, re.S)
    arr = json.loads(m.group(1))
    cache = {}
    def h(i):
        if isinstance(i, int):
            if i < 0: return None
            if i in cache: return cache[i]
            v = arr[i]
            if isinstance(v, list):
                if v and isinstance(v[0], str) and v[0] in ("Reactive","ShallowReactive","Ref","ShallowRef","EmptyRef","EmptyShallowRef","NuxtError","Set","Map","Date","Object"):
                    tag = v[0]
                    if tag in ("EmptyRef","EmptyShallowRef"): return None
                    if tag == "Date": return v[1]
                    if tag == "Set": return [h(x) for x in v[1:]]
                    if tag == "Map":
                        return {str(h(v[k])): h(v[k+1]) for k in range(1, len(v), 2)}
                    r = h(v[1]); cache[i] = r; return r
                out = []; cache[i] = out
                out.extend(h(x) for x in v); return out
            if isinstance(v, dict):
                out = {}; cache[i] = out
                for k, x in v.items(): out[k] = h(x)
                return out
            return v
        return i
    return h(0)
if __name__ == "__main__":
    d = load_nuxt(open(sys.argv[1], encoding="utf-8").read())
    json.dump(d, open(sys.argv[2], "w"), ensure_ascii=False, indent=1, default=str)
    print("ok")
