import re, json, sys
def parse(html):
    m = re.search(r'var ytInitialData = (\{.*?\});</script>', html, re.S)
    data = json.loads(m.group(1))
    out = []
    def walk(o):
        if isinstance(o, dict):
            if 'videoRenderer' in o:
                v = o['videoRenderer']
                title = ''.join(x.get('text','') for x in v.get('title',{}).get('runs',[]))
                vc = v.get('viewCountText',{}).get('simpleText') or ''.join(x.get('text','') for x in v.get('viewCountText',{}).get('runs',[]))
                n = int(re.sub(r'\D','',vc) or 0)
                out.append(dict(id=v['videoId'], title=title, views_text=vc, views=n,
                    length=v.get('lengthText',{}).get('simpleText'),
                    channel=''.join(x.get('text','') for x in v.get('ownerText',{}).get('runs',[])),
                    published=v.get('publishedTimeText',{}).get('simpleText'),
                    live=any('LIVE' in json.dumps(b) for b in v.get('badges',[]))))
                return
            for x in o.values(): walk(x)
        elif isinstance(o, list):
            for x in o: walk(x)
    walk(data)
    return out, data
if __name__ == '__main__':
    res, data = parse(open(sys.argv[1], encoding='utf-8').read())
    for r in res: print(r)
    keys=set()
    def kw(o):
        if isinstance(o,dict):
            for k,v in o.items():
                if k.endswith('Renderer') or k.endswith('ViewModel'): keys.add(k)
                kw(v)
        elif isinstance(o,list):
            for x in o: kw(x)
    kw(data); print(sorted(keys))
